import json
import requests
import uuid
import time
import random
import re
import trafilatura
from concurrent.futures import ThreadPoolExecutor, as_completed

# ================= CONFIGURATION =================
# Input file generated by LLM (must use the v5.1 Prompt structure)
INPUT_FILE = 'topics_plan.json'
OUTPUT_FILE = 'docs.json'

# GDELT Doc 2.0 API Endpoint
GDELT_API_URL = "https://api.gdeltproject.org/api/v2/doc/doc"

# Set to True to scrape full text using Trafilatura
SCRAPE_FULL_TEXT = True 

# Target document counts per category
TARGET_COUNTS = {
    'gold': 50,          
    'hard_negative': 10, 
    'soft_negative': 10   
}

# Fetch multiplier: Request 5x more URLs to ensure we have enough after deduplication
FETCH_MULTIPLIER = 2 

# Quality Control Thresholds (Fail-Fast Logic)
# If Gold docs < 10, skip the topic immediately.
MIN_VALID_GOLD = 10
MIN_VALID_DISTRACTORS = 4

# Starting ID for the final dataset
STARTING_TOPIC_ID = 100 

# Number of concurrent threads for scraping
MAX_WORKERS = 16
# =================================================

def normalize_title(title):
    """
    Normalizes a title string for deduplication purposes.
    Removes common suffixes (e.g., " - BBC News") and non-alphanumeric characters.
    """
    if not title: return ""
    # Remove common site suffixes like " | Reuters", " - CNN"
    t = re.sub(r'\s*[-|]\s*.*$', '', title)
    # Remove special chars and lowercase
    t = re.sub(r'[^a-zA-Z0-9]', '', t).lower()
    return t

def make_request_with_retry(params, max_retries=3):
    """
    Sends a request to GDELT API with robust error handling.
    """
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
    }

    for attempt in range(max_retries):
        try:
            time.sleep(0.5) 
            response = requests.get(GDELT_API_URL, params=params, headers=headers, timeout=20)
            
            if response.status_code == 429:
                wait_time = 5 + attempt * 5
                print(f"    [Warning] 429 Rate Limit. Sleeping for {wait_time}s...")
                time.sleep(wait_time)
                continue
            
            if "text/html" in response.headers.get('Content-Type', ''):
                if attempt == max_retries - 1:
                     print(f"    [Error] API returned HTML instead of JSON.")
                continue

            response.raise_for_status()
            data = response.json()
            return data.get('articles', [])
            
        except requests.exceptions.JSONDecodeError:
            print(f"    [Warning] API returned non-JSON content (Attempt {attempt+1}/{max_retries})")
        except Exception as e:
            print(f"    [Warning] Request failed: {e}")
    
    return []

def fetch_gdelt_urls_smart(query, target_count):
    """
    Fetches URLs for a single query string.
    """
    if not query: return []

    cleaned_query = query.replace('2024', '').replace('2025', '').strip()
    
    request_count = target_count * FETCH_MULTIPLIER
    if request_count > 250: request_count = 250
    
    base_params = {
        'mode': 'ArtList',
        'maxrecords': request_count,
        'format': 'json',
        'sort': 'DateDesc',
        'timespan': '3y' 
    }

    # Strategy A: Strict Search
    params_strict = base_params.copy()
    params_strict['query'] = f"{cleaned_query} sourcelang:eng"
    articles = make_request_with_retry(params_strict)
    
    # Strategy B: Loose Search (Fallback)
    if len(articles) < target_count and '"' in cleaned_query:
        loose_query = cleaned_query.replace('"', '').strip()
        print(f"      -> Low results ({len(articles)}). Retrying with loose query: {loose_query}")
        
        params_loose = base_params.copy()
        params_loose['query'] = f"{loose_query} sourcelang:eng"
        more_articles = make_request_with_retry(params_loose)
        
        seen_urls = {art['url'] for art in articles}
        for art in more_articles:
            if art['url'] not in seen_urls:
                articles.append(art)
                
    return articles

def scrape_content(url):
    """
    Scrapes full text content from a URL using Trafilatura.
    """
    if not SCRAPE_FULL_TEXT: return None
    try:
        downloaded = trafilatura.fetch_url(url)
        if downloaded:
            return trafilatura.extract(downloaded, include_comments=False, include_tables=False)
    except:
        return None
    return None

def process_single_article(article):
    """
    Scrapes content and formats the article object.
    Returns None if scraping fails or content is too short.
    """
    url = article.get('url', '')
    title = article.get('title', 'No Title')
    domain = article.get('domain', 'Unknown Source')
    image_url = article.get('socialimage', '')
    
    full_text = scrape_content(url)
    
    # Quality Filter: Content must be meaningful (>200 chars)
    if not full_text or len(full_text) < 200:
        return None

    snippet = full_text[:150].replace('\n', ' ') + "..."

    return {
        "title": title,
        "link": url,
        "snippet": snippet,
        "source": domain,
        "imageUrl": image_url,
        "content": full_text,
        "uuid": str(uuid.uuid4())
    }

def process_category_docs(query_list, count_needed, category_label):
    """
    Handles the full pipeline for a specific category:
    Fetch -> Dedupe -> Scrape -> Filter -> Sample
    """
    if not query_list: return []
    
    all_raw_articles = []
    
    # 1. Fetch
    for q in query_list:
        if q:
            print(f"  - Fetching {category_label} Query: {q}")
            urls = fetch_gdelt_urls_smart(q, count_needed)
            all_raw_articles.extend(urls)
    
    # 2. Deduplication
    seen_urls = set()
    seen_titles = set()
    unique_candidates = []
    
    for art in all_raw_articles:
        url = art.get('url')
        if url in seen_urls: continue
        
        norm_title = normalize_title(art.get('title', ''))
        
        # If title is long enough, use it for semantic dedupe
        if len(norm_title) > 10:
            if norm_title in seen_titles: continue
            seen_titles.add(norm_title)
        
        seen_urls.add(url)
        unique_candidates.append(art)
    
    print(f"    -> Aggregated {len(all_raw_articles)} raw. Kept {len(unique_candidates)} unique candidates.")
    
    # 3. Scraping
    valid_docs = []
    with ThreadPoolExecutor(max_workers=MAX_WORKERS) as executor:
        future_to_art = {executor.submit(process_single_article, art): art for art in unique_candidates}
        
        for future in as_completed(future_to_art):
            try:
                res = future.result()
                if res: 
                    valid_docs.append(res)
            except Exception:
                pass
    
    # 4. Sampling
    if len(valid_docs) > count_needed:
        print(f"    -> Scraped {len(valid_docs)} valid docs. Sampling down to {count_needed}.")
        selected_docs = random.sample(valid_docs, count_needed)
    else:
        print(f"    -> Scraped {len(valid_docs)} valid docs (Target: {count_needed}). Keeping all.")
        selected_docs = valid_docs
        
    return selected_docs

def build_dataset():
    """
    Main execution flow with Fail-Fast logic.
    """
    try:
        with open(INPUT_FILE, 'r', encoding='utf-8') as f:
            topics_plan = json.load(f)
    except FileNotFoundError:
        print(f"[Error] {INPUT_FILE} not found. Please run the LLM prompt first.")
        return

    final_dataset = []
    current_topic_id_counter = STARTING_TOPIC_ID

    print(f"Starting processing for {len(topics_plan)} topics...")

    for index, topic_item in enumerate(topics_plan):
        topic_name = topic_item.get('topic')
        print(f"\n[{index+1}/{len(topics_plan)}] Processing Topic: {topic_name}")
        
        # ========================================================
        # STEP 1: Process GOLD Docs First (FAIL-FAST CHECK)
        # ========================================================
        gold_docs = process_category_docs(
            topic_item.get('gold_queries', []), 
            TARGET_COUNTS['gold'], 
            "GOLD"
        )
        
        # Check immediately: Do we have enough Gold docs?
        if len(gold_docs) < MIN_VALID_GOLD:
            print(f"  [SKIP] Dropped topic '{topic_name}' immediately.")
            print(f"         Reason: Insufficient Gold Docs ({len(gold_docs)} < {MIN_VALID_GOLD}).")
            # Skip fetching Hard/Soft entirely to save time/resources
            continue
            
        # ========================================================
        # STEP 2: Process Distractors (Only if Gold is valid)
        # ========================================================
        
        # Process Hard Negatives
        hard_docs = process_category_docs(
            topic_item.get('hard_negative_queries', []), 
            TARGET_COUNTS['hard_negative'], 
            "HARD"
        )

        # Process Soft Negatives
        soft_docs = process_category_docs(
            topic_item.get('soft_negative_queries', []), 
            TARGET_COUNTS['soft_negative'], 
            "SOFT"
        )

        # ========================================================
        # STEP 3: Final Distractor Check & Assembly
        # ========================================================
        total_distractors = len(hard_docs) + len(soft_docs)
        
        if total_distractors < MIN_VALID_DISTRACTORS:
            print(f"  [SKIP] Dropped topic '{topic_name}'.")
            print(f"         Reason: Insufficient Distractors ({total_distractors} < {MIN_VALID_DISTRACTORS}).")
            continue

        # Assemble Final Entry
        all_docs = gold_docs + hard_docs + soft_docs
        random.shuffle(all_docs) 
        
        topic_entry = {
            "topic_id": current_topic_id_counter,
            "topic": topic_name,
            "docs": all_docs
        }
        final_dataset.append(topic_entry)
        current_topic_id_counter += 1

    # Save to JSON
    with open(OUTPUT_FILE, 'w', encoding='utf-8') as f:
        json.dump(final_dataset, f, indent=4, ensure_ascii=False)
    
    print(f"\n[Success] Dataset saved to {OUTPUT_FILE}")
    print(f"Total valid topics generated: {len(final_dataset)}")

if __name__ == "__main__":
    build_dataset()